Gõ vào chương trình sau:  
```cpp
#include <iostream.h>

void main()
{

cout << "1 + 2 = " << 1+ 2 << "\n";

cout << "1.0 / 2 = " << 1.0 / 2 << "\n";

cout << "1 / 2.0 = " << 1 / 2.0 << "\n";

cout << "1.0 / 2.0 = " << 1.0 / 2.0 << "\n";

cout << "11 % 8 = " << 11 % 8 << "\n";

cout << "-11 % 8 = " << -11 % 8 << "\n";

cout << "11 % -8 = " << 11 % -8 << "\n";

cout << "-11 % -8 = " << -11 % -8 << "\n";

cout << "(1 + 2 > 1 * 2) = " << (1 + 2 > 1 * 2) << "\n";

cout << "(1 + 2 <= 1 * 2) = " << (1 + 2 <= 1 * 2) << "\n";

cout << "('B' > 'a' && 1 + 2 > 1 * 2) = " << ('B' > 'a' && 1 + 2 > 1 * 2) << "\n";

cout << "('B' > 'a' || 1 + 2 > 1 * 2) = " << ('B' > 'a' || 1 + 2 > 1 * 2) << "\n";

cout << "sizeof(int) = " << sizeof(int) << "\n";

cout << "sizeof(double) = " << sizeof(double) << "\n";

cout << "sizeof(long int) = " << sizeof(long int) << "\n";

cout << "sizeof(1.0 / 2) = " << sizeof(int) << "\n";

cout << "(4 & 5) = " << (4 & 5) << "\n";

cout << "(4 | 5) = " << (4 | 5) << "\n";

cout << "(4 ^ 5) = " << (4 ^ 5) << "\n";

cout << "(2 << 3 )= " << (2 << 3) << "\n";

cout << "(8 >> 3 )= " << (8 >> 3) << "\n";

}
